-- Demo e-commerce schema for Db2 LUW 11.5.
-- Run with:  db2 connect to COMMERCE && db2 -tvf sql/schema.sql
-- (seed.py also applies this file when the tables do not exist.)
-- Identity columns are GENERATED BY DEFAULT so seed.py can bulk-load explicit keys
-- and then restart each identity above the loaded maximum.

CREATE SCHEMA COMMERCE;

CREATE TABLE COMMERCE.CUSTOMERS (
    customer_id  INTEGER      NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 1),
    name         VARCHAR(100) NOT NULL,
    email        VARCHAR(255) NOT NULL,
    created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT TIMESTAMP,
    CONSTRAINT PK_CUSTOMERS PRIMARY KEY (customer_id)
);

CREATE TABLE COMMERCE.PRODUCTS (
    product_id   INTEGER       NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 1),
    name         VARCHAR(200)  NOT NULL,
    description  VARCHAR(1000),
    category     VARCHAR(50)   NOT NULL,
    price        DECIMAL(10,2) NOT NULL,
    image_url    VARCHAR(500),
    CONSTRAINT PK_PRODUCTS PRIMARY KEY (product_id)
);

CREATE INDEX COMMERCE.IX_PRODUCTS_CATEGORY ON COMMERCE.PRODUCTS (category);

CREATE TABLE COMMERCE.INVENTORY (
    product_id   INTEGER   NOT NULL,
    quantity     INTEGER   NOT NULL,
    updated_at   TIMESTAMP NOT NULL DEFAULT CURRENT TIMESTAMP,
    CONSTRAINT PK_INVENTORY PRIMARY KEY (product_id),
    CONSTRAINT FK_INVENTORY_PRODUCT FOREIGN KEY (product_id) REFERENCES COMMERCE.PRODUCTS (product_id)
);

CREATE TABLE COMMERCE.ORDERS (
    order_id     BIGINT        NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 1),
    customer_id  INTEGER       NOT NULL,
    order_date   TIMESTAMP     NOT NULL DEFAULT CURRENT TIMESTAMP,
    status       VARCHAR(20)   NOT NULL,
    total        DECIMAL(12,2) NOT NULL,
    CONSTRAINT PK_ORDERS PRIMARY KEY (order_id),
    CONSTRAINT FK_ORDERS_CUSTOMER FOREIGN KEY (customer_id) REFERENCES COMMERCE.CUSTOMERS (customer_id)
);

CREATE INDEX COMMERCE.IX_ORDERS_CUSTOMER ON COMMERCE.ORDERS (customer_id);

CREATE INDEX COMMERCE.IX_ORDERS_ORDER_DATE ON COMMERCE.ORDERS (order_date DESC);

CREATE TABLE COMMERCE.ORDER_ITEMS (
    order_id     BIGINT        NOT NULL,
    product_id   INTEGER       NOT NULL,
    quantity     INTEGER       NOT NULL,
    unit_price   DECIMAL(10,2) NOT NULL,
    CONSTRAINT PK_ORDER_ITEMS PRIMARY KEY (order_id, product_id),
    CONSTRAINT FK_ORDER_ITEMS_ORDER FOREIGN KEY (order_id) REFERENCES COMMERCE.ORDERS (order_id),
    CONSTRAINT FK_ORDER_ITEMS_PRODUCT FOREIGN KEY (product_id) REFERENCES COMMERCE.PRODUCTS (product_id)
);

CREATE INDEX COMMERCE.IX_ORDER_ITEMS_ORDER_ID ON COMMERCE.ORDER_ITEMS (order_id);
CREATE INDEX COMMERCE.IX_ORDER_ITEMS_PRODUCT_ID ON COMMERCE.ORDER_ITEMS (product_id);

CREATE TABLE COMMERCE.ORDERS_ARCHIVE (
    order_id     BIGINT        NOT NULL,
    customer_id  INTEGER       NOT NULL,
    order_date   TIMESTAMP     NOT NULL,
    status       VARCHAR(20)   NOT NULL,
    total        DECIMAL(12,2) NOT NULL,
    CONSTRAINT PK_ORDERS_ARCHIVE PRIMARY KEY (order_id)
);
